      for (size_t i = 0; i < (size_t)CAMW * CAMH * 3; i++) rfnv = (rfnv ^ rfb[i]) * 16777619u;
      printf("renderwram: fnv=%08X\n", rfnv);
      { const char* op = getenv("CT_BATTLE_RENDEROUT");
        if (op) { FILE* of = fopen(op, "wb");
                  if (of) { uint32_t wh[2] = { (uint32_t)CAMW, (uint32_t)CAMH }; fwrite(wh, 4, 2, of);
                            fwrite(rfb, (size_t)CAMW * CAMH * 3, 1, of); fclose(of); } } }
