        if (pb & PAD_UP) upPressed = 1;
        if (pb & PAD_DOWN) downPressed = 1;
        if (pb & PAD_LEFT) leftPressed = 1;
        if (pb & PAD_RIGHT) rightPressed = 1;
        if (pb & PAD_ST) nmOk = 1;
        if (pb & PAD_B) nmDel = 1;
