        if (pb & PAD_UP) upPressed = 1;
        if (pb & PAD_DOWN) downPressed = 1;
        if (pb & PAD_LEFT) leftPressed = 1;
        if (pb & PAD_RIGHT) rightPressed = 1;
        if (k == SDLK_F8) battleEndReq = 1;                 // consumed only while battlePhase (below)
        if (pb & PAD_A) nmType = 1;                         // A: type the highlighted key
