        wr[0x0283] = (uint8_t)wd.mv.posX; wr[0x0284] = (uint8_t)(wd.mv.posX >> 8);
        wr[0x0285] = (uint8_t)wd.mv.posY; wr[0x0286] = (uint8_t)(wd.mv.posY >> 8);
